if (btnConfirmCreate) {
    btnConfirmCreate.addEventListener('click', async () => {
        const name = document.getElementById('new-model-name').value.trim();
        if (!name) {
            alert('Please enter a model name');
            return;
        }

        const boardSize = parseInt(document.getElementById('new-model-board-size').value);
        const komi = parseFloat(document.getElementById('new-model-komi').value);
        const ruleset = document.getElementById('new-model-ruleset').value;

        const spGames = parseInt(document.getElementById('new-model-sp').value);
        const evalGames = parseInt(document.getElementById('new-model-eval').value);
        const mctsSims = parseInt(document.getElementById('new-model-mcts').value);
        const cpuct = parseFloat(document.getElementById('new-model-cpuct').value);
        const lr = parseFloat(document.getElementById('new-model-lr').value);

        btnConfirmCreate.disabled = true;
        btnConfirmCreate.textContent = 'Creating...';

        try {
            const res = await fetch('/models/api/create', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    name: name,
                    board_size: boardSize,
                    komi: komi,
                    ruleset: ruleset,
                    num_self_play_games: spGames,
                    eval_games: evalGames,
                    num_simulations: mctsSims,
                    c_puct: cpuct,
                    learning_rate: lr
                })
            });

            const data = await res.json();
            if (!res.ok) {
                alert(data.error || 'Failed to create model');
                btnConfirmCreate.disabled = false;
                btnConfirmCreate.textContent = 'Create Model';
                return;
            }

            // If successful, reload to show it
            window.location.reload();
        } catch (err) {
            console.error(err);
            alert('Error creating model');
            btnConfirmCreate.disabled = false;
            btnConfirmCreate.textContent = 'Create Model';
        }
    });

