    # Build policy vector from visit counts with temperature scaling (AlphaZero formulation: pi_a ~ N_a^(1/tau))
    action_size = state.board_size * state.board_size + 1  # +1 for pass
    policy = np.zeros(action_size, dtype=np.float32)

    # Find the most visited child for argmax (temp -> 0)
    max_visits = max(child.visit_count for child in root.children.values()) if root.children else 0

    for action, child in root.children.items():
        if action == MOVE_PASS:
            idx = action_size - 1  # Pass is the last action
        else:
            idx = action[0] * state.board_size + action[1]

        if temperature < 0.01:
            # One-hot encoding for tau -> 0
            policy[idx] = 1.0 if child.visit_count == max_visits else 0.0
        else:
            policy[idx] = float(child.visit_count) ** (1.0 / temperature)

    # Apply temperature to visit counts for move selection
    action = self._select_action(root, temperature)

    # Normalize policy to probabilities (training target)
    total = policy.sum()
    if total > 0:
        policy = policy / total

    return action, policy

